"fleet-manage":{k:"PRO FLOTILY",t:"Správa flotily",l:"Centrální prostor pro vozidla, řidiče, přiřazení a dokumenty.",cards:[["01","Vozidla","Přidávejte a upravujte vozidla své flotily a jejich základní provozní údaje."],["02","Řidiči","Evidujte řidiče, jejich kontakty a stav v rámci vašeho provozu."],["03","Přiřazení","Udržujte přehled o tom, který řidič používá které vozidlo."]],steps:["Založte flotilu","Přidejte vozidla a řidiče","Přiřaďte provoz"]},
