about:{k:"SPOLEČNOST",t:"O Helpsni",l:"Digitální platforma pro jednodušší správu dopravního provozu.",cards:[["01","Jednoduchost","Soustředíme se na přehledné nástroje místo zbytečné složitosti."],["02","Pro řidiče","Řidič má vlastní účet a prostor pro své registrační údaje."],["03","Pro flotily","Flotily získávají nástroje pro správu vozidel a řidičů."]]},
mission:{k:"SPOLEČNOST",t:"Naše poslání",l:"Pomáhat dopravcům a řidičům zvládat provoz přehledněji.",cards:[["01","Přehled","Důležité provozní informace mají být dostupné na jednom místě."],["02","Bezpečnost","Přístup k účtům a datům oddělujeme podle oprávnění."],["03","Budoucnost","Platformu stavíme tak, aby bylo možné přidávat další užitečné funkce."]]},
contact:{k:"SPOLEČNOST",t:"Kontakt",l:"Máte otázku, návrh nebo zájem o spolupráci? Tato sekce bude sloužit jako kontaktní místo Helpsni.",cards:[["01","Podpora","Pro technické otázky připravujeme centrum podpory."],["02","Spolupráce","Pro flotily a další partnery připravujeme samostatný kontaktní proces."],["03","Obecné dotazy","Obecné informace budeme postupně doplňovat."]]},
career:{k:"SPOLEČNOST",t:"Kariéra",l:"Informace o pracovních příležitostech a spolupráci s Helpsni.",cards:[["01","Otevřené pozice","Aktuální nabídky zveřejníme přímo zde."],["02","Technologie","Helpsni stavíme jako moderní webovou platformu."],["03","Spolupráce","Pro vybrané role bude možné nabídnout i externí spolupráci."]]},
support:{k:"PODPORA",t:"Centrum podpory",l:"Jedno místo pro nejčastější situace řidičů a flotil.",cards:[["01","Registrace a účet","Pomoc s vytvořením účtu, přihlášením a základními údaji profilu."],["02","Dokumenty a provoz","Postup pro práci s dokumenty, vozidly, řidiči a jejich přiřazením."],["03","Technické potíže","Zkontrolujte účet, stav služby a konkrétní chybovou zprávu. Pokud problém trvá, připravte si popis problému pro podporu."]],faq:[["Nemohu se přihlásit","Zkontrolujte e-mail a heslo. Pokud problém trvá, použijte podporu a uveďte, co se při přihlášení zobrazuje."],["Dokument byl odmítnut","Zkontrolujte typ dokumentu, čitelnost a jeho platnost a podle pokynů nahrajte správnou verzi."],["Dokument se blíží expiraci","Nahrajte aktuální dokument co nejdříve, aby byl jeho stav možné včas zkontrolovat."],["Mám problém s vozidlem nebo řidičem","Ve flotile zkontrolujte stav záznamu, přiřazení a případné dokumenty."]],steps:["Najděte odpověď","Zkontrolujte svůj účet","Pokračujte v platformě"]},
help:{k:"PODPORA",t:"Nápověda",l:"Praktické návody pro používání jednotlivých částí Helpsni.",cards:[["01","Řidič","Registrace, profil, dokumenty a další kroky po vytvoření účtu."],["02","Flotila","Vozidla, řidiči, dokumenty a jejich přiřazení v jednom přehledu."],["03","Účet","Přihlášení, práce s účtem a základní bezpečnostní pravidla."]],steps:["Vyberte svou roli","Otevřete příslušnou část","Postupujte podle návodu"]},
faq:{k:"PODPORA",t:"Časté dotazy",l:"Odpovědi na nejčastější otázky uživatelů Helpsni.",faq:[["Jak se zaregistruji jako řidič?","Vyberete registraci řidiče a vyplníte základní údaje. Další kroky se zobrazí podle průběhu registrace."],["Co potřebuji před registrací připravit?","Doporučujeme mít připravené základní osobní a řidičské údaje. Konkrétní dokumenty budou záviset na způsobu zapojení do provozu."],["Mohu spravovat více vozidel?","Ano. Správa flotily je určena pro evidenci více vozidel a řidičů."],["Mohu propojit řidiče s vozidlem?","Ano. Flotila může udržovat přehled o přiřazení řidičů k vozidlům."],["Kde jsou uložené dokumenty?","Dokumenty jsou ukládány v privátním prostoru s přístupem podle oprávnění."],["Bude Helpsni objednávat jízdy na webu?","Ne v současném rozsahu. Web slouží především jako prezentační a registrační prostředí; objednávání jízd plánujeme řešit v aplikaci."]]},
"driver-guide":{k:"PRO ŘIDIČE",t:"Příručka pro řidiče",l:"Praktický průvodce registrací, profilem, dokumenty a přípravou na provoz.",cards:[["01","Registrace","Vytvořte účet, doplňte své údaje a dokončete jednotlivé kroky registrace."],["02","Dokumenty","Nahrajte požadované dokumenty a sledujte jejich stav a platnost."],["03","Připravenost","Před zahájením provozu si zkontrolujte údaje profilu, dokumenty a stav registrace."]],steps:["Vytvořte účet","Doplňte profil","Nahrajte dokumenty","Dokončete kontrolu"]},
"driver-safety":{k:"BEZPEČNOST",t:"Bezpečnost řidiče",l:"Základní pravidla pro bezpečný a profesionální provoz. Praktické funkce budou součástí aplikace.",cards:[["01","Před jízdou","Zkontrolujte vozidlo, své údaje a připravenost k jízdě."],["02","Během provozu","Řiďte bezpečně, soustřeďte se na provoz a zachovávejte profesionální jednání."],["03","Problém nebo incident","Při nehodě nebo bezpečnostním problému nejprve zajistěte bezpečí a podle situace kontaktujte příslušnou pomoc."]],steps:["Zkontrolujte připravenost","Dodržujte bezpečný provoz","Nahlaste problém"]},
"community-rules":{k:"PRAVIDLA PLATFORMY",t:"Pravidla Helpsni",l:"Základní standardy chování pro řidiče a flotilové partnery.",cards:[["01","Respekt","Komunikace mezi účastníky platformy má být slušná, věcná a profesionální."],["02","Bezpečnost","Nikdo nesmí vědomě ohrožovat sebe, ostatní osoby ani provoz."],["03","Pravdivé údaje","Údaje účtu, řidiče, vozidla a dokumentů musí odpovídat skutečnosti."]],steps:["Chovejte se profesionálně","Chraňte bezpečnost","Udržujte správné údaje"]},
security:{k:"BEZPEČNOST",t:"Bezpečnost",l:"Bezpečnost účtů a oddělení dat je součástí základu platformy.",cards:[["01","Přihlášení","Účty používají zabezpečenou autentizaci."],["02","Oddělení dat","Data jednotlivých flotil jsou oddělena pomocí oprávnění a databázových pravidel."],["03","Dokumenty","Citlivé dokumenty jsou ukládány do privátních úložišť."]]},
"account-security":{k:"BEZPEČNOST",t:"Ochrana účtu",l:"Základní pravidla pro bezpečné používání účtu Helpsni.",cards:[["01","Silné heslo","Používejte jedinečné heslo, které nepoužíváte na jiných službách."],["02","Nesdílet přístup","Přihlašovací údaje nikdy neposílejte dalším osobám."],["03","Kontrola účtu","Při podezřelé aktivitě kontaktujte podporu a změňte heslo."]]},
"data-protection":{k:"BEZPEČNOST",t:"Ochrana dat",l:"Přístup k provozním údajům je řízen podle účtu a oprávnění.",cards:[["01","Oddělené účty","Uživatelé pracují pouze s daty, ke kterým mají oprávnění."],["02","Řízení přístupu","Databázová pravidla omezují přístup mezi jednotlivými účty a flotilami."],["03","Privátní dokumenty","Dokumentové úložiště není veřejně přístupné."]]},
