brno:{k:"LOKALITY",t:"Brno",l:"Samostatná sekce pro informace související s provozem Helpsni v Brně.",cards:[["01","Řidiči","Informace pro řidiče v Brně."],["02","Flotily","Informace pro flotilové partnery v Brně."],["03","Podpora","Místní informace budeme postupně doplňovat."]]},
