chomutov:{k:"LOKALITY",t:"Chomutov",l:"Helpsni připravuje své první lokální zaměření na Chomutov a okolí.",cards:[["01","Řidiči","Informace a registrace pro řidiče, kteří se chtějí zapojit do Helpsni."],["02","Flotily","Prostor pro dopravce a menší i větší provozy v regionu."],["03","Rozvoj","Další lokální informace budeme doplňovat podle skutečného spuštění služby."]]},louny:{k:"LOKALITY",t:"Louny",l:"Helpsni připravuje lokální informace pro Louny a okolí.",cards:[["01","Řidiči","Registrace a informace pro řidiče v regionu."],["02","Flotily","Nástroje pro správu vozidel a řidičů."],["03","Rozvoj","Lokální obsah budeme rozšiřovat s rozvojem služby."]]},most:{k:"LOKALITY",t:"Most",l:"Helpsni připravuje lokální informace pro Most a okolí.",cards:[["01","Řidiči","Registrace a informace pro řidiče v regionu."],["02","Flotily","Nástroje pro správu vozidel a řidičů."],["03","Rozvoj","Lokální obsah budeme rozšiřovat s rozvojem služby."]]},zatec:{k:"LOKALITY",t:"Žatec",l:"Helpsni připravuje lokální informace pro Žatec a okolí.",cards:[["01","Řidiči","Registrace a informace pro řidiče v regionu."],["02","Flotily","Nástroje pro správu vozidel a řidičů."],["03","Rozvoj","Lokální obsah budeme rozšiřovat s rozvojem služby."]]},cities:{k:"PRO MĚSTA",t:"Řešení pro města",l:"Základ pro budoucí spolupráci měst, dopravců a řidičů.",cards:[["01","Přehled","Digitální prostředí pro evidenci a komunikaci."],["02","Dopravci","Možnost pracovat s registrovanými dopravními partnery."],["03","Řidiči","Prostor pro budoucí nástroje určené městům a řidičům."]]},
